mapper.insert:
INSERT INTO stat.map_building (district_code, building_id, height, under_construction, attrs, geom) SELECT v.code, v.building_id, v.height, v.uc, coalesce(v.attrs::jsonb, '{}'::jsonb), ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_Transform(ST_GeomFromEWKB(decode(v.hex, 'hex')), 3857)), 3)) FROM (VALUES
(#{b.code}, #{b.buildingId}, #{b.height}::numeric, #{b.underConstruction}::boolean, #{b.attrs}, #{b.ewkbHex})
) AS v(code, building_id, height, uc, attrs, hex)

INSERT INTO stat.map_plot (district_code, plot_id, status, use_desc, attrs, geom) SELECT v.code, v.plot_id, v.status, v.use_desc, coalesce(v.attrs::jsonb, '{}'::jsonb), ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_Transform(ST_GeomFromEWKB(decode(v.hex, 'hex')), 3857)), 3)) FROM (VALUES
(#{p.code}, #{p.plotId}, #{p.status}, #{p.useDesc}, #{p.attrs}, #{p.ewkbHex})
) AS v(code, plot_id, status, use_desc, attrs, hex)
